#ifndef ECW_SDK_H
#define ECW_SDK_H
#include <stdbool.h>
#include <stdint.h>
#include "ecw_spi_poll.h"
/* Private SDK boundary. Production implementation is ecw_sdk_p16.c. */
uintptr_t ecw_sdk_lock(void);
void ecw_sdk_unlock(uintptr_t key);
bool ecw_sdk_thread_ready(void);
/* Startup configuration is generated by the selected SDK project. No DFS. */
bool ecw_sdk_clock_ready(void);
bool ecw_sdk_in_isr(void);
uint32_t ecw_sdk_time_ms(void);
int ecw_sdk_delay_ms(uint32_t ms);
int ecw_sdk_gpio_open(unsigned pin, bool output, bool high);
/* Private explicit pull path; legacy callers retain no-pull behavior. */
int ecw_sdk_gpio_open_pull(unsigned pin, bool output, bool high, unsigned pull);
int ecw_sdk_gpio_read(unsigned pin, unsigned *value);
int ecw_sdk_gpio_write(unsigned pin, bool high);
int ecw_sdk_gpio_close(unsigned pin);
/* Board SPI slot 0 -> P16 SPI1, fixed 8-bit. Legacy open uses mode 0/MSB. */
int ecw_sdk_spi_open(unsigned instance, const uint8_t *pins, uint32_t rate_hz);
int ecw_sdk_spi_open_config(unsigned instance, const uint8_t *pins,
                            const Ecw6700PortConfig *config);
int ecw_sdk_spi_close(unsigned instance, const uint8_t *pins);
EcwSpiPollResult ecw_sdk_spi_transfer(unsigned instance, const uint8_t *tx, uint8_t *rx, size_t n,
                                      uint32_t timeout_ms);
/* Owned fixed-Board basic adapters; rate is bus Hz / UART baud / PWM Hz. */
#include "bsp_ecw6700.h"
#include "ecw_serial_poll.h"
int ecw_basic_open(const Ecw6700Port *, uint32_t);
int ecw_basic_open_config(const Ecw6700Port *, const Ecw6700PortConfig *);
int ecw_basic_close(const Ecw6700Port *);
EcwIoResult ecw_basic_i2c(uint8_t, const uint8_t *, size_t, const uint8_t *, size_t, uint8_t *,
                          size_t, uint32_t);
EcwIoResult ecw_basic_uart(unsigned, const uint8_t *, uint8_t *, size_t, uint32_t);
BspStatus ecw_basic_pwm(const Ecw6700Port *, size_t, uint16_t, bool);
#endif
